// Model tests for every build (plan-v2-final.md, Sections 9 and 11).
// Run: npm test   (Node >= 18, no dependencies)
// Expected values come from tests/expected.json, generated by the independent Python
// reference (ap-sim/) via tools/build_expected.py. Written before either website build.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const EXPECTED = JSON.parse(readFileSync(join(ROOT, 'tests/expected.json'), 'utf8'));
const TOL = EXPECTED.meta.tolerances;
const BAND = { low: 54, high: 144 };

const BUILDS = [
  { name: 'claude', dir: 'site' },
  { name: 'gemini', dir: 'site/gemini' },
];
// Optional extra build directory (used to self-test this harness): EXTRA_BUILD=/path/to/dir npm test
if (process.env.EXTRA_BUILD) BUILDS.push({ name: 'extra', dir: process.env.EXTRA_BUILD });

function nearRel(actual, expected, key, rel = TOL.scalar_rel) {
  assert.equal(typeof actual, 'number', `${key}: expected a number, got ${actual}`);
  assert.ok(Number.isFinite(actual), `${key}: not finite (${actual})`);
  const err = expected === 0 ? Math.abs(actual) : Math.abs(actual - expected) / Math.abs(expected);
  assert.ok(err <= rel, `${key}: got ${actual}, expected ${expected} (off by ${(err * 100).toFixed(3)} %)`);
}
function nearAbs(actual, expected, key, tol) {
  assert.equal(typeof actual, 'number', `${key}: expected a number, got ${actual}`);
  assert.ok(Number.isFinite(actual), `${key}: not finite (${actual})`);
  assert.ok(Math.abs(actual - expected) <= tol, `${key}: got ${actual}, expected ${expected} (tolerance ±${tol})`);
}
const collect = (failures, fn) => { try { fn(); } catch (e) { failures.push(e.message); } };

// --- data audit: every value object must cite a known source ---
test('data.js: every value has a known sourceId', async () => {
  const { DATA } = await import(pathToFileURL(join(ROOT, 'site/js/data.js')));
  const missing = [];
  (function walk(o, path) {
    if (o && typeof o === 'object' && !Array.isArray(o)) {
      if ('value' in o || 'sourceId' in o) {
        if (!o.sourceId || !(o.sourceId in DATA.sources)) missing.push(path);
        return;
      }
      for (const [k, v] of Object.entries(o)) if (k !== 'sources' && k !== 'meta') walk(v, `${path}.${k}`);
    }
  })(DATA, 'DATA');
  assert.deepEqual(missing, [], `values without a valid sourceId: ${missing.join(', ')}`);
});

for (const build of BUILDS) {
  const modelPath = resolve(ROOT, build.dir, 'js/model.js');
  describe(`${build.name} build (${build.dir}/js/model.js)`, { skip: !existsSync(modelPath) && 'model.js not built yet' }, () => {
    let M;
    const load = async () => (M ??= await import(pathToFileURL(modelPath)));

    test('exports the API contract', async () => {
      await load();
      for (const fn of ['linearModel', 'nonlinearGain', 'halfRule', 'imcTuning', 'margins', 'simulate', 'metrics']) {
        assert.equal(typeof M[fn], 'function', `missing export ${fn}()`);
      }
      assert.equal(typeof M.DEFAULT_INPUTS, 'object', 'missing export DEFAULT_INPUTS');
    });

    test('DEFAULT_INPUTS match plan v2 §9.1', async () => {
      await load();
      const failures = [];
      for (const [k, v] of Object.entries(EXPECTED.defaultInputs)) {
        collect(failures, () => {
          assert.ok(k in M.DEFAULT_INPUTS, `DEFAULT_INPUTS missing key "${k}"`);
          if (typeof v === 'number') nearRel(M.DEFAULT_INPUTS[k], v, `DEFAULT_INPUTS.${k}`);
          else assert.deepEqual(M.DEFAULT_INPUTS[k], v, `DEFAULT_INPUTS.${k}`);
        });
      }
      assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
    });

    test('linear model, nonlinear gain, half rule', async () => {
      await load();
      const failures = [];
      const lm = M.linearModel();
      for (const [k, v] of Object.entries(EXPECTED.linearModel)) collect(failures, () => nearRel(lm[k], v, `linearModel.${k}`));
      for (const { dU, gain } of EXPECTED.nonlinearGain) collect(failures, () => nearRel(M.nonlinearGain(dU), gain, `nonlinearGain(${dU})`));
      const hr = M.halfRule();
      for (const sec of ['sopdt', 'fopdt']) {
        for (const [k, v] of Object.entries(EXPECTED.halfRule[sec])) collect(failures, () => nearRel(hr[sec]?.[k], v, `halfRule.${sec}.${k}`));
      }
      assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
    });

    test(`IMC tuning (${EXPECTED.imcTuning.length} cases)`, async () => {
      await load();
      const failures = [];
      for (const { inputs, expect } of EXPECTED.imcTuning) {
        const out = M.imcTuning(inputs);
        for (const [k, v] of Object.entries(expect)) collect(failures, () => nearRel(out[k], v, `imcTuning(${JSON.stringify(inputs)}).${k}`));
      }
      assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
    });

    test(`stability margins (${EXPECTED.margins.length} cases)`, async () => {
      await load();
      const failures = [];
      for (const { name, inputs, expect } of EXPECTED.margins) {
        const out = M.margins(inputs);
        for (const [k, v] of Object.entries(expect)) collect(failures, () => nearRel(out[k], v, `margins[${name}].${k}`));
      }
      assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
    });

    for (const sc of EXPECTED.scenarios) {
      test(`scenario ${sc.name}: ${sc.note}`, async () => {
        await load();
        const r = M.simulate(sc.inputs);
        const failures = [];
        const dt = { ...EXPECTED.defaultInputs, ...sc.inputs }.dt;
        sc.times.forEach((t, j) => {
          const i = Math.round(t / dt);
          collect(failures, () => nearAbs(r.G[i], sc.G[j], `G(t=${t})`, TOL.G_abs));
          collect(failures, () => nearAbs(r.U[i], sc.U[j], `U(t=${t})`, TOL.U_abs));
        });
        collect(failures, () => assert.ok(r.G.every(Number.isFinite), 'G contains NaN/Infinity'));
        collect(failures, () => assert.ok(r.U.every((u) => u >= -1e-9 && u <= 115 + 1e-9), 'U outside [0, 115]'));
        collect(failures, () => assert.equal(r.valid, sc.valid, 'valid'));
        collect(failures, () => assert.equal(r.warnings.length > 0, sc.hasWarning, `warnings: ${JSON.stringify(r.warnings)}`));
        collect(failures, () => nearAbs(r.bolusDelivered, sc.bolusDelivered, 'bolusDelivered', 1.0));
        const m = M.metrics(r, BAND);
        const e = sc.metrics;
        collect(failures, () => nearAbs(m.peak, e.peak, 'metrics.peak', TOL.peak_nadir_abs));
        collect(failures, () => nearAbs(m.nadir, e.nadir, 'metrics.nadir', TOL.peak_nadir_abs));
        collect(failures, () => nearAbs(m.pct_in_band, e.pct_in_band, 'metrics.pct_in_band', TOL.pct_abs));
        collect(failures, () => nearAbs(m.pct_below_70, e.pct_below_70, 'metrics.pct_below_70', TOL.pct_abs));
        collect(failures, () => nearRel(m.IAE, e.IAE, 'metrics.IAE', TOL.IAE_rel));
        collect(failures, () => nearRel(m.insulin_total, e.insulin_total, 'metrics.insulin_total', TOL.insulin_rel));
        collect(failures, () => nearAbs(m.insulin_ff, e.insulin_ff, 'metrics.insulin_ff', 1.0));
        collect(failures, () => assert.equal(m.stayed_in_band, e.stayed_in_band, 'metrics.stayed_in_band'));
        assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
      });
    }

    test('simulate({}) uses DEFAULT_INPUTS', async () => {
      await load();
      const a = M.simulate({});
      const sc = EXPECTED.scenarios.find((s) => s.name === 'ex23_6e_feedback_only');
      nearAbs(a.G[Math.round(sc.times.at(-1) / 0.1)], sc.G.at(-1), 'G(t_end)', TOL.G_abs);
    });

    test('seeded noise is reproducible (same seed -> identical, different seed -> different)', async () => {
      await load();
      const a = M.simulate({ noise_sd: 5, seed: 7 });
      const b = M.simulate({ noise_sd: 5, seed: 7 });
      const c = M.simulate({ noise_sd: 5, seed: 8 });
      assert.deepEqual(a.Gm, b.Gm);
      assert.deepEqual(a.U, b.U);
      assert.notDeepEqual(a.Gm, c.Gm);
      assert.ok(a.U.every((u) => u >= -1e-9 && u <= 115 + 1e-9), 'U outside [0, 115] with noise');
    });
  });
}
